    '1 month+': '1 месяц и больше', '10 minutes before': 'За 10 минут', '2 days before': 'За 2 дня',
    '3 hours before': 'За 3 часа', '30 minutes before': 'За 30 минут',
    'API key (optional)': 'Ключ API (необязательно)', 'Accessibility needs': 'Потребности в доступности',
